#include <IQM/hdrvdp3/srgb_quality96_runtime_double.h>
#include <IQM/hdrvdp3/csf.h>
#include <vulkan_instance.h>
#include <fstream>
#include <iostream>
#include <bit>
#include <limits>
using namespace IQM::HDRVDP3;namespace fs=std::filesystem;
std::vector<double> read(const fs::path&p,size_t n){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f||f.tellg()!=std::streamoff(n*8))throw std::runtime_error("Reference shape "+p.string());std::vector<double> v(n);f.seekg(0);f.read(reinterpret_cast<char*>(v.data()),n*8);return v;}
std::vector<double> rows(std::vector<double> v,unsigned w){auto r=v;for(unsigned y=0;y<w;++y)for(unsigned x=0;x<w;++x)r[y*w+x]=v[x*w+y];return r;}
int main(int argc,char**argv){try{if(argc!=4)throw std::invalid_argument("Usage: v8-runtime cpu-root fresh-output");fs::path runtime=argv[1],cpu=argv[2],out=argv[3];if(fs::exists(out)||!fs::create_directories(out))throw std::invalid_argument("Fresh output");auto model=load_srgb_quality96_runtime_double(runtime,"oled");IQM::Bin::VulkanInstance instance(true,"NVIDIA",true);SRGBQuality96GPUDouble gpu(*instance.physicalDevice(),*instance.device(),*instance.queue(),instance.queueFamilyIndex,true,model.shaders,model.projection,model.mutual,model.neighbor,model.pyramid,model.comparison,model.jnd,model.csf);size_t words=0;auto compare=[&](const std::vector<double>&a,const std::vector<double>&b,const std::string& name){if(a.size()!=b.size())throw std::runtime_error("Shape");for(size_t i=0;i<a.size();++i)if(std::bit_cast<uint64_t>(a[i])!=std::bit_cast<uint64_t>(b[i]))throw std::runtime_error(name+" bits at "+std::to_string(i));words+=a.size();};const unsigned widths[]{96,96,48,24,12};
 for(std::string native:{"native","native_ramps","native_identity_v2"})for(std::string display:{"led-lcd-srgb","led-lcd-wcg","oled"}){auto r=rows(read(cpu/native/(display+"_1_adaptation.f64"),9216),96),t=rows(read(cpu/native/(display+"_2_adaptation.f64"),9216),96);auto mean=quality_log_adaptation_double(r,t);auto metadata=read(cpu/native/(display+"_quality_band5_base_metadata.f64"),3);for(unsigned b=0;b<5;++b){auto result=gpu.csf(mean,b,metadata[1]);const auto prefix=(cpu/native/(display+"_quality_band"+std::to_string(b+1))).string();for(auto item:{std::pair{"log_adaptation",&result.log_adaptation},std::pair{"csf",&result.sensitivity},std::pair{"noise",&result.noise}}){compare(*item.second,rows(read(prefix+"_"+item.first+".f64",size_t(widths[b])*widths[b]),widths[b]),item.first);std::ofstream f(out/(native+"_"+display+"_band"+std::to_string(b+1)+"_"+item.first+".f64"),std::ios::binary);f.write(reinterpret_cast<const char*>(item.second->data()),item.second->size()*8);}compare({result.table.begin(),result.table.end()},read(prefix+"_csf_table.f64",256),"CPU table");if(b==4)compare({result.base_luminance},{metadata[2]},"CPU base luminance");}}
 size_t nativeWords=words;const auto grid=csf_log_luminance_grid();for(unsigned seed=0;seed<5;++seed){std::vector<double> input(9216);for(size_t i=0;i<input.size();++i)input[i]=seed==0?-7.:seed==1?7.:seed==2?grid[i%256]:seed==3?(i==48*96+48?5.:-5.):double(int(i%113)-56)*.13;for(unsigned b=0;b<5;++b){double frequency=seed==3?0.:1.25;auto actual=gpu.csf(input,b,frequency),expected=quality_csf_double(input,b,frequency);compare(actual.log_adaptation,expected.log_adaptation,"control log");compare(actual.sensitivity,expected.sensitivity,"control csf");compare(actual.noise,expected.noise,"control noise");compare({actual.table.begin(),actual.table.end()},{expected.table.begin(),expected.table.end()},"control CPU table");if(b==4)compare({actual.base_luminance},{expected.base_luminance},"control CPU luminance");}}
 unsigned rejected=0;auto reject=[&](auto action){try{action();}catch(const std::exception&){++rejected;return;}throw std::runtime_error("Invalid CSF input accepted");};std::vector<double> input(9216,0.);reject([&]{gpu.csf({},0,0);});reject([&]{gpu.csf(input,5,0);});for(double f:{-1.,std::numeric_limits<double>::quiet_NaN(),std::numeric_limits<double>::infinity()})reject([&]{gpu.csf(input,0,f);});for(double v:{std::numeric_limits<double>::quiet_NaN(),std::numeric_limits<double>::infinity()}){input[0]=v;reject([&]{gpu.csf(input,0,0);});}input.assign(9215,0.);reject([&]{gpu.csf(input,0,0);});std::ofstream(out/"PASS.txt")<<nativeWords<<" native hybrid CSF Double words exact;"<<words-nativeWords<<" control words exact;"<<rejected<<" rejection checks\n";std::cout<<words<<" hybrid CSF words exact;CPU model/base nonlinear scalar retained\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
